CREATE TABLE geo_query_prices(id integer PRIMARY KEY CHECK(id=1),unit_cents integer NOT NULL DEFAULT 0 CHECK(unit_cents BETWEEN 0 AND 1000000),enabled boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1);
INSERT INTO geo_query_prices(id) VALUES(1);
CREATE TABLE geo_query_quotes(id text PRIMARY KEY,site_id text NOT NULL REFERENCES sites(id),actor_id text NOT NULL REFERENCES users(id),snapshot jsonb NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '2 minutes',submitted_key text);
ALTER TABLE geo_query_tasks ADD COLUMN quote_id text REFERENCES geo_query_quotes(id),ADD COLUMN billing_id text UNIQUE REFERENCES billing_orders(id),ADD COLUMN phase text NOT NULL DEFAULT 'done' CHECK(phase IN ('submit','submitting','poll','archive','done','review')),ADD COLUMN next_run_at timestamptz NOT NULL DEFAULT now(),ADD COLUMN lease_until timestamptz,ADD COLUMN lease_token text,ADD COLUMN attempts integer NOT NULL DEFAULT 0,ADD COLUMN archive_attempts integer NOT NULL DEFAULT 0,ADD COLUMN result jsonb,ADD COLUMN archive_error text,ADD COLUMN archive_state text NOT NULL DEFAULT 'none' CHECK(archive_state IN ('none','pending','saved','failed','unavailable'));
CREATE INDEX geo_query_dispatch ON geo_query_tasks(phase,next_run_at) WHERE phase IN ('submit','poll','archive');
